use refract_core::{RefractError,RefractResult};
use rusqlite::{params,OptionalExtension};
use serde::{Deserialize,Serialize};
use std::collections::{BTreeMap,BTreeSet};
use sync_engine::secure::{self,Contact,LocalIdentity,json};
pub use sync_engine::secure::Contact as DeviceContact;
mod exchange;
pub use exchange::{ExportRequest,ImportRequest,ExchangeResult};
#[cfg(test)]mod tests;
fn err(e:impl std::fmt::Display)->RefractError{RefractError::storage(e.to_string())}
fn invalid(s:&str)->RefractError{RefractError::invalid(s)}
fn now()->i64{std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_secs()as i64}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)]#[serde(deny_unknown_fields)]pub struct Member{pub contact:Contact,pub role:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)]#[serde(deny_unknown_fields)]pub struct Policy{pub version:u32,pub id:String,pub name:String,pub owner:String,pub epoch:u64,pub members:Vec<Member>}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)]#[serde(deny_unknown_fields)]pub struct SignedPolicy{pub data:Policy,pub signature:String}
impl SignedPolicy{
 fn validate(&self)->RefractResult<()>{let p=&self.data;if p.version!=1||uuid::Uuid::parse_str(&p.id).is_err()||p.name.trim().is_empty()||p.name.chars().count()>120||p.epoch==0||p.members.is_empty()||p.members.len()>30{return Err(invalid("Invalid workspace policy"));}let mut keys=BTreeSet::new();for m in &p.members{m.contact.validate()?;let key=&m.contact.data.signing_key;if !keys.insert(key)||!["owner","editor","viewer"].contains(&m.role.as_str())||(m.role=="owner")!=(key==&p.owner){return Err(invalid("Invalid member role or duplicate device key"));}}if self.role(&p.owner)!="owner"{return Err(invalid("Workspace owner missing"));}secure::verify(&p.owner,&format!("refract-policy-v1:{}",json(p)?),&self.signature)}
 fn role(&self,key:&str)->&str{self.data.members.iter().find(|m|m.contact.data.signing_key==key).map(|m|m.role.as_str()).unwrap_or("removed")}
 fn member(&self,key:&str)->RefractResult<&Member>{self.data.members.iter().find(|m|m.contact.data.signing_key==key).ok_or_else(||invalid("Device is not a selected member"))}
}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq)]#[serde(deny_unknown_fields)]pub struct Revision{
 pub id:String,pub entry_id:String,pub parents:Vec<String>,pub kind:String,pub title:String,pub body:String,
 pub reply_to:Option<String>,pub collection_id:Option<String>,pub done:bool,pub deleted:bool,
 pub anchor:Option<Anchor>,pub source_label:Option<String>,pub source_url:Option<String>,
 pub declared_author:String,pub recorded_ts:i64,
}
#[derive(Debug,Serialize)]pub struct EntryView{pub id:String,pub versions:Vec<Revision>,pub conflict:bool,pub history_count:usize,pub resolution:Option<AnchorResolution>}
#[derive(Debug,Serialize)]pub struct AnchorResolution{pub status:String,pub local_item_id:Option<String>,pub block_idx:Option<u32>,pub explanation:String}
#[derive(Debug,Serialize)]pub struct WorkspaceView{pub id:String,pub name:String,pub owner:String,pub my_key:String,pub role:String,pub epoch:u64,pub members:Vec<Member>,pub exchange_enabled:bool,pub local_revision:i64,pub entries:Vec<EntryView>,pub pending_transfers:usize,pub limitations:Vec<String>}
#[derive(Debug,Default,Deserialize)]#[serde(default,deny_unknown_fields)]pub struct NewEntry{
 pub workspace_id:String,pub kind:String,pub title:String,pub body:String,pub reply_to:Option<String>,pub collection_id:Option<String>,
 pub local_item_id:Option<String>,pub block_idx:Option<u32>,pub quote:String,pub include_context:bool,pub share_source_label:bool,pub share_source_url:bool,
}
#[derive(Debug,Deserialize)]#[serde(deny_unknown_fields)]pub struct EditEntry{pub workspace_id:String,pub entry_id:String,pub chosen_revision:String,pub title:String,pub body:String,pub done:bool,pub deleted:bool}
fn check_revision(r:&Revision)->RefractResult<()>{
 if uuid::Uuid::parse_str(&r.id).is_err()||uuid::Uuid::parse_str(&r.entry_id).is_err()||r.parents.len()>32||r.parents.iter().collect::<BTreeSet<_>>().len()!=r.parents.len()||!["highlight","note","comment","reference","collection"].contains(&r.kind.as_str())||r.title.trim().is_empty()||r.title.chars().count()>200||r.body.chars().count()>4000||r.source_label.as_ref().is_some_and(|s|s.chars().count()>200)||r.source_url.as_ref().is_some_and(|s|s.chars().count()>2000){return Err(invalid("Invalid revision or entry limit exceeded"));}
 secure::unhex::<32>(&r.declared_author)?;
 if let Some(a)=&r.anchor{if uuid::Uuid::parse_str(&a.document_id).is_err()||a.quote.trim().is_empty()||a.quote.chars().count()>1200||a.prefix.chars().count()>40||a.suffix.chars().count()>40||a.heading.as_ref().is_some_and(|s|s.chars().count()>120)||a.relative_position.is_some_and(|v|!v.is_finite()||!(0.0..=1.0).contains(&v))||a.content_hash.len()!=64||a.document_version.len()!=64{return Err(invalid("Invalid anchor"));}}
 Ok(())
}
fn validate_records(records:&BTreeMap<String,Revision>)->RefractResult<()>{
 if records.len()>512||records.values().map(|r|&r.entry_id).collect::<BTreeSet<_>>().len()>150||json(records)?.len()>900_000{return Err(invalid("Workspace limit reached: 150 entries, 512 revisions and 900 KB logical history; nothing was discarded"));}
 for(id,r)in records{check_revision(r)?;if id!=&r.id{return Err(invalid("Revision ID mismatch"));}for p in &r.parents{let parent=records.get(p).ok_or_else(||invalid("Missing revision parent"))?;if parent.entry_id!=r.entry_id{return Err(invalid("Cross-entry revision parent"));}}}
 for r in records.values(){for linked in [&r.reply_to,&r.collection_id].into_iter().flatten(){if linked==&r.entry_id||!records.values().any(|v|&v.entry_id==linked&&(r.collection_id.as_ref()!=Some(linked)||v.kind=="collection")){return Err(invalid("Invalid thread/collection reference"));}}}
 let mut resolved=BTreeSet::new();loop{let before=resolved.len();for r in records.values(){if r.parents.iter().all(|p|resolved.contains(p)){resolved.insert(r.id.clone());}}if before==resolved.len(){break;}}
 if resolved.len()!=records.len(){return Err(invalid("Cyclic revision history"));}Ok(())
}
fn heads(records:&BTreeMap<String,Revision>,entry:&str)->Vec<Revision>{let parents=records.values().flat_map(|r|r.parents.iter()).collect::<BTreeSet<_>>();records.values().filter(|r|r.entry_id==entry&&!parents.contains(&r.id)).cloned().collect()}
impl Store{
 fn margin_identity_private(&self)->RefractResult<LocalIdentity>{let stored:Option<String>=self.conn.query_row("SELECT private_json FROM margin_identity WHERE id=1",[],|r|r.get(0)).optional().map_err(err)?;if let Some(s)=stored{return serde_json::from_str(&s).map_err(err);}let me=LocalIdentity::new("This device")?;self.conn.execute("INSERT INTO margin_identity(id,private_json) VALUES(1,?1)",params![json(&me)?]).map_err(err)?;Ok(me)}
 pub fn margin_contact(&self)->RefractResult<Contact>{Ok(self.margin_identity_private()?.contact)}
 pub fn margin_set_name(&self,name:&str)->RefractResult<Contact>{let mut me=self.margin_identity_private()?;me.contact.data.name=name.trim().into();me.contact.signature=secure::sign(&me.signing_secret,&format!("refract-contact-v1:{}",json(&me.contact.data)?))?;me.contact.validate()?;self.conn.execute("UPDATE margin_identity SET private_json=?1 WHERE id=1",params![json(&me)?]).map_err(err)?;Ok(me.contact)}
 fn margin_load(&self,id:&str)->RefractResult<(SignedPolicy,AnnotationDoc,bool,i64)>{let(policy,state,enabled,revision):(String,Vec<u8>,bool,i64)=self.conn.query_row("SELECT policy_json,state,exchange_enabled,local_revision FROM margin_workspaces WHERE id=?1",params![id],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?))).optional().map_err(err)?.ok_or_else(||invalid("Workspace not found"))?;let policy:SignedPolicy=serde_json::from_str(&policy).map_err(err)?;policy.validate()?;let mut doc=AnnotationDoc::new();doc.merge(&state)?;Ok((policy,doc,enabled,revision))}
 fn margin_records(doc:&AnnotationDoc)->RefractResult<BTreeMap<String,Revision>>{doc.entries()?.into_iter().map(|(id,s)|serde_json::from_str(&s).map(|r|(id,r)).map_err(err)).collect()}
 fn margin_writer(&self,p:&SignedPolicy)->RefractResult<LocalIdentity>{let me=self.margin_identity_private()?;if !["owner","editor"].contains(&p.role(&me.contact.data.signing_key)){return Err(invalid("Read-only or removed devices cannot modify shared records"));}Ok(me)}
 fn margin_log(&self,id:&str,kind:&str,detail:&str)->RefractResult<()>{self.conn.execute("INSERT INTO margin_history(workspace_id,kind,detail,recorded_ts) VALUES(?1,?2,?3,?4)",params![id,kind,detail,now()]).map_err(err)?;Ok(())}
 pub fn margin_create(&self,name:&str)->RefractResult<WorkspaceView>{let me=self.margin_identity_private()?;let p=Policy{version:1,id:uuid::Uuid::new_v4().to_string(),name:name.trim().into(),owner:me.contact.data.signing_key.clone(),epoch:1,members:vec![Member{contact:me.contact.clone(),role:"owner".into()}]};let signed=SignedPolicy{signature:secure::sign(&me.signing_secret,&format!("refract-policy-v1:{}",json(&p)?))?,data:p};signed.validate()?;let mut doc=AnnotationDoc::new();self.conn.execute("INSERT INTO margin_workspaces(id,policy_json,state,created_ts,updated_ts) VALUES(?1,?2,?3,?4,?4)",params![signed.data.id,json(&signed)?,doc.export_state()?,now()]).map_err(err)?;self.margin_view(&signed.data.id)}
 pub fn margin_list(&self)->RefractResult<Vec<WorkspaceView>>{let mut stmt=self.conn.prepare("SELECT id FROM margin_workspaces ORDER BY updated_ts DESC,id LIMIT 100").map_err(err)?;let ids=stmt.query_map([],|r|r.get::<_,String>(0)).map_err(err)?.collect::<Result<Vec<_>,_>>().map_err(err)?;ids.iter().map(|id|self.margin_view(id)).collect()}
 pub fn margin_enable(&self,id:&str,enabled:bool)->RefractResult<()>{let(p,_,_,_)=self.margin_load(id)?;if p.role(&self.margin_contact()?.data.signing_key)=="removed"&&enabled{return Err(invalid("Removed device cannot enable exchange"));}self.conn.execute("UPDATE margin_workspaces SET exchange_enabled=?2 WHERE id=?1",params![id,enabled]).map_err(err)?;Ok(())}
 pub fn margin_member(&self,id:&str,contact:&Contact,role:&str)->RefractResult<WorkspaceView>{
  contact.validate()?;let(mut p,_,_,_)=self.margin_load(id)?;let me=self.margin_identity_private()?;if p.data.owner!=me.contact.data.signing_key||contact.data.signing_key==p.data.owner||!["editor","viewer","removed"].contains(&role){return Err(invalid("Only owner can select or remove another device"));}p.data.members.retain(|m|m.contact.data.signing_key!=contact.data.signing_key);if role!="removed"{p.data.members.push(Member{contact:contact.clone(),role:role.into()});}p.data.members.sort_by(|a,b|a.contact.data.signing_key.cmp(&b.contact.data.signing_key));p.data.epoch=p.data.epoch.checked_add(1).ok_or_else(||invalid("Epoch exhausted"))?;p.signature=secure::sign(&me.signing_secret,&format!("refract-policy-v1:{}",json(&p.data)?))?;p.validate()?;
  let tx=self.conn.unchecked_transaction().map_err(err)?;tx.execute("UPDATE margin_workspaces SET policy_json=?2,local_revision=local_revision+1,updated_ts=?3 WHERE id=?1",params![id,json(&p)?,now()]).map_err(err)?;tx.execute("INSERT INTO margin_contacts(workspace_id,peer_key,contact_json) VALUES(?1,?2,?3) ON CONFLICT(workspace_id,peer_key) DO UPDATE SET contact_json=excluded.contact_json",params![id,contact.data.signing_key,json(contact)?]).map_err(err)?;self.margin_log(id,"policy_change",&format!("Device {} role {role}; policy epoch {}. Offline peers learn changes only after importing the signed policy.",contact.data.signing_key,p.data.epoch))?;tx.commit().map_err(err)?;self.margin_view(id)
 }
 pub fn margin_preview(&self,input:&NewEntry)->RefractResult<Revision>{
  let(p,doc,_,_)=self.margin_load(&input.workspace_id)?;let me=self.margin_writer(&p)?;let mut r=Revision{id:uuid::Uuid::new_v4().to_string(),entry_id:uuid::Uuid::new_v4().to_string(),parents:vec![],kind:input.kind.clone(),title:input.title.trim().into(),body:input.body.clone(),reply_to:input.reply_to.clone(),collection_id:input.collection_id.clone(),done:false,deleted:false,anchor:None,source_label:None,source_url:None,declared_author:me.contact.data.signing_key,recorded_ts:now()};
  if let Some(id)=&input.local_item_id{let item=self.get_item(id)?.ok_or_else(||invalid("Local source not found"))?;let mut anchor=annotation_engine::build_anchor(&item.blocks,input.block_idx.ok_or_else(||invalid("Choose source block"))?,&input.quote)?;anchor.document_id=self.conn.query_row("SELECT document_id FROM margin_bindings WHERE workspace_id=?1 AND item_id=?2",params![input.workspace_id,id],|r|r.get(0)).optional().map_err(err)?.unwrap_or_else(||uuid::Uuid::new_v4().to_string());if !input.include_context{anchor.prefix.clear();anchor.suffix.clear();anchor.heading=None;}r.anchor=Some(anchor);if input.share_source_label{r.source_label=item.title.map(|s|s.chars().take(200).collect());}if input.share_source_url{r.source_url=item.source_url;}}
  if r.kind=="highlight"&&r.anchor.is_none(){return Err(invalid("Highlights require an explicit quoted local source"));}let mut records=Self::margin_records(&doc)?;records.insert(r.id.clone(),r.clone());validate_records(&records)?;Ok(r)
 }
 pub fn margin_publish(&self,input:&NewEntry)->RefractResult<WorkspaceView>{let r=self.margin_preview(input)?;let(_,mut doc,_,_)=self.margin_load(&input.workspace_id)?;doc.upsert(&r.id,&json(&r)?)?;let tx=self.conn.unchecked_transaction().map_err(err)?;if let(Some(anchor),Some(item))=(&r.anchor,&input.local_item_id){tx.execute("INSERT OR IGNORE INTO margin_bindings(workspace_id,document_id,item_id) VALUES(?1,?2,?3)",params![input.workspace_id,anchor.document_id,item]).map_err(err)?;}self.margin_persist(&input.workspace_id,&mut doc,"local_revision",&r.id)?;tx.commit().map_err(err)?;self.margin_view(&input.workspace_id)}
 fn margin_persist(&self,id:&str,doc:&mut AnnotationDoc,kind:&str,detail:&str)->RefractResult<()>{let records=Self::margin_records(doc)?;validate_records(&records)?;self.conn.execute("UPDATE margin_workspaces SET state=?2,local_revision=local_revision+1,updated_ts=?3 WHERE id=?1",params![id,doc.export_state()?,now()]).map_err(err)?;self.margin_log(id,kind,detail)}
 pub fn margin_edit(&self,input:&EditEntry)->RefractResult<WorkspaceView>{let(p,mut doc,_,_)=self.margin_load(&input.workspace_id)?;let me=self.margin_writer(&p)?;let mut records=Self::margin_records(&doc)?;let h=heads(&records,&input.entry_id);let mut r=h.iter().find(|r|r.id==input.chosen_revision).cloned().ok_or_else(||invalid("Choose a current revision; conflicts require an explicit version choice"))?;r.parents=h.iter().map(|r|r.id.clone()).collect();r.id=uuid::Uuid::new_v4().to_string();r.title=input.title.trim().into();r.body=input.body.clone();r.done=input.done;r.deleted=input.deleted;r.declared_author=me.contact.data.signing_key;r.recorded_ts=now();records.insert(r.id.clone(),r.clone());validate_records(&records)?;doc.upsert(&r.id,&json(&r)?)?;let tx=self.conn.unchecked_transaction().map_err(err)?;self.margin_persist(&input.workspace_id,&mut doc,"local_revision",&r.id)?;tx.commit().map_err(err)?;self.margin_view(&input.workspace_id)}
 pub fn margin_bind(&self,id:&str,document:&str,item:&str)->RefractResult<AnchorResolution>{let(_,doc,_,_)=self.margin_load(id)?;let records=Self::margin_records(&doc)?;let anchor=records.values().filter_map(|r|r.anchor.as_ref()).find(|a|a.document_id==document).ok_or_else(||invalid("Shared document identity not found"))?;self.get_item(item)?.ok_or_else(||invalid("Local source not found"))?;self.conn.execute("INSERT INTO margin_bindings(workspace_id,document_id,item_id) VALUES(?1,?2,?3) ON CONFLICT(workspace_id,document_id) DO UPDATE SET item_id=excluded.item_id",params![id,document,item]).map_err(err)?;self.margin_resolve(id,anchor)}
 fn margin_resolve(&self,id:&str,a:&Anchor)->RefractResult<AnchorResolution>{let binding:Option<String>=self.conn.query_row("SELECT item_id FROM margin_bindings WHERE workspace_id=?1 AND document_id=?2",params![id,a.document_id],|r|r.get(0)).optional().map_err(err)?;if let Some(item_id)=binding{if let Some(item)=self.get_item(&item_id)?{let(status,block)=annotation_engine::resolve_document_anchor(a,&a.document_id,&item.blocks);let status=serde_json::to_value(status).map_err(err)?.as_str().unwrap_or("lost").to_owned();return Ok(AnchorResolution{status,local_item_id:Some(item_id),block_idx:block,explanation:"Exact quote with recorded context/heading is required. Position is a hint, never a tie-breaker. Ambiguous or missing quotes stay unresolved.".into()});}}Ok(AnchorResolution{status:"unbound".into(),local_item_id:None,block_idx:None,explanation:"No local source has been explicitly matched to this shared document identity. No private library search or automatic attachment was performed.".into()})}
 pub fn margin_view(&self,id:&str)->RefractResult<WorkspaceView>{let(p,doc,enabled,revision)=self.margin_load(id)?;let me=self.margin_contact()?.data.signing_key;let records=Self::margin_records(&doc)?;let ids=records.values().map(|r|r.entry_id.clone()).collect::<BTreeSet<_>>();let mut entries=Vec::new();for id_entry in ids{let versions=heads(&records,&id_entry);let resolution=versions.first().and_then(|r|r.anchor.as_ref()).map(|a|self.margin_resolve(id,a)).transpose()?;entries.push(EntryView{id:id_entry.clone(),conflict:versions.len()>1,history_count:records.values().filter(|r|r.entry_id==id_entry).count(),versions,resolution});}let pending:i64=self.conn.query_row("SELECT COUNT(*) FROM margin_transfers WHERE workspace_id=?1 AND direction='out' AND acknowledged_ts IS NULL",params![id],|r|r.get(0)).map_err(err)?;Ok(WorkspaceView{id:id.into(),name:p.data.name.clone(),owner:p.data.owner.clone(),role:p.role(&me).into(),my_key:me,epoch:p.data.epoch,members:p.data.members,exchange_enabled:enabled,local_revision:revision,entries,pending_transfers:pending as usize,limitations:vec!["Only selected annotation/reference/research-list content is exchanged. Private library originals, private notes, decisions and unrelated metadata are never synchronized.".into(),"Exchange is manual, optional and foreground-only. Export is not delivery; a signed receipt is a peer's claim of import, not proof of reading or universal convergence.".into(),"Device keys identify cryptographic devices, not verified people. Verify full fingerprints independently. Editors may edit all shared content; revision attribution is peer-supplied, not verified individual authorship.".into(),"Policy changes reach offline devices only on subsequent exchange. Revocation cannot erase previously received copies or prevent offline peers using an older policy before learning the change.".into(),"Private signing/decryption keys are stored in the local app database, not a hardware keystore. Device/database compromise is outside this protection. Protocol is not independently security-audited.".into(),"150 entries, 512 immutable revisions, 900 KB logical history per workspace. Concurrent versions (including deletion) remain visible until explicitly resolved; no silent truncation.".into()]})}
 pub fn margin_history(&self,id:&str)->RefractResult<serde_json::Value>{let(_,doc,_,_)=self.margin_load(id)?;let revisions=Self::margin_records(&doc)?.into_values().collect::<Vec<_>>();let mut stmt=self.conn.prepare("SELECT kind,detail,recorded_ts FROM margin_history WHERE workspace_id=?1 ORDER BY id DESC LIMIT 100").map_err(err)?;let events=stmt.query_map(params![id],|r|Ok(serde_json::json!({"kind":r.get::<_,String>(0)?,"detail":r.get::<_,String>(1)?,"recorded_ts":r.get::<_,i64>(2)?}))).map_err(err)?.collect::<Result<Vec<_>,_>>().map_err(err)?;Ok(serde_json::json!({"revisions":revisions,"events":events,"attribution":"Revision author fields are supplied by collaborators. Verified exporter keys appear separately in import events."}))}
}
